<script>
export default {
  props: {
    status: {
      type: String,
      default: 'todo'
    }
  },
  emits: ['status-changed'],
  data() {
    return {
      statusOptions: [
        { value: 'todo', label: 'Todo', icon: 'fa-solid fa-circle' },
        { value: 'pending', label: 'Pending', icon: 'fa-solid fa-clock' },
        { value: 'done', label: 'Done', icon: 'fa-solid fa-check-circle' }
      ]
    }
  },
  computed: {
    currentStatus() {
      return this.status || 'todo'
    },
    statusLabel() {
      const opt = this.statusOptions.find(s => s.value === this.currentStatus)
      return opt?.label || 'Unknown'
    },
    statusIcon() {
      const opt = this.statusOptions.find(s => s.value === this.currentStatus)
      const baseIcon = opt?.icon || 'fa-solid fa-circle'
      const colorMap = {
        'todo': 'text-base-content/50',
        'pending': 'text-warning',
        'done': 'text-success'
      }
      return `${baseIcon} ${colorMap[this.currentStatus] || ''}`
    }
  },
  methods: {
    selectStatus(newStatus) {
      if (newStatus !== this.currentStatus) {
        this.$emit('status-changed', newStatus)
      }
    }
  }
}
</script>
